408	/// Acquire an exclusive sidecar `.lock` file around a write operation, with a
409	/// 30-second timeout so a stranded lock (crashed tomlctl, OS-mandatory Windows
410	/// lock, heavy contention) produces a clear error instead of hanging forever.
411	fn with_exclusive_lock<R>(path: &Path, f: impl FnOnce() -> Result<R>) -> Result<R> {
412	    use fs4::fs_std::FileExt;
413	    use std::time::{Duration, Instant};
414	
415	    let lock_path = path.with_extension(match path.extension().and_then(|s| s.to_str()) {
416	        Some(ext) => format!("{}.lock", ext),
417	        None => "lock".to_string(),
418	    });
419	    let lock_file = std::fs::OpenOptions::new()
420	        .create(true)
421	        .truncate(false)
422	        .read(true)
423	        .write(true)
424	        .open(&lock_path)
425	        .with_context(|| format!("opening lock file {}", lock_path.display()))?;
426	
427	    let timeout = Duration::from_secs(30);
428	    let retry_delay = Duration::from_millis(500);
429	    let start = Instant::now();
430	    loop {
431	        match lock_file.try_lock_exclusive() {
432	            Ok(true) => break,
433	            Ok(false) => {
434	                if start.elapsed() >= timeout {
435	                    bail!(
436	                        "lock held on {} for 30 seconds — another tomlctl process may be hanging. If no tomlctl process is running, check for stale lock and delete {} manually.",
437	                        lock_path.display(),
438	                        lock_path.display()
439	                    );
440	                }
441	                std::thread::sleep(retry_delay);
442	            }
443	            Err(e) => {
444	                return Err(anyhow!(e)).with_context(|| {
445	                    format!("acquiring exclusive lock on {}", lock_path.display())
446	                });
447	            }
448	        }
449	    }
450	
451	    let result = f();
452	    // Drop releases the lock automatically; no explicit unlock needed.
453	    let _ = lock_file;
454	    result
455	}
