457	/// Refuse to write to files outside the current repo's `.claude/` directory
458	/// unless `--allow-outside` was passed on this invocation. Protects against
459	/// agent-influenced `artifacts.*` paths pointing at e.g. credential files.
460	///
461	/// Resolution strategy:
462	///   1. Canonicalise the target (parent if file doesn't exist yet).
463	///   2. Find the git top-level via `git rev-parse --show-toplevel`.
464	///      Fall back to CWD if git is missing or we're not inside a repo.
465	///   3. Assert canonical target lies under `<root>/.claude/`.
466	fn guard_write_path(file: &Path, allow_outside: bool) -> Result<()> {
467	    let canonical = canonicalize_for_write(file).with_context(|| {
468	        format!("canonicalising write target {}", file.display())
469	    })?;
470	
471	    let root = repo_or_cwd_root()?;
472	    let claude_dir = root.join(".claude");
473	    // Canonicalise the allowed root too so the prefix comparison is apples-to-apples
474	    // (on Windows, canonicalize yields extended-length `\\?\` paths).
475	    let claude_canonical = match claude_dir.canonicalize() {
476	        Ok(p) => p,
477	        Err(_) => claude_dir.clone(),
478	    };
479	
480	    if canonical.starts_with(&claude_canonical) {
481	        return Ok(());
482	    }
483	
484	    if allow_outside {
485	        eprintln!(
486	            "tomlctl: warning: writing outside .claude/ (path resolves to {}) — proceeding because --allow-outside was set",
487	            canonical.display()
488	        );
489	        return Ok(());
490	    }
491	
492	    bail!(
493	        "refusing to write outside .claude/ (path resolves to {}); pass --allow-outside to override",
494	        canonical.display()
495	    )
496	}
