1311	                    obj.insert("id".into(), JsonValue::String(id.into()));
1312	                    obj.insert("class".into(), JsonValue::String("symbol-missing".into()));
1313	                    obj.insert("file".into(), JsonValue::String(file.into()));
1314	                    obj.insert("symbol".into(), JsonValue::String(symbol.into()));
1315	                    out.push(JsonValue::Object(obj));
1316	                }
1317	            }
1318	        }
1319	
1320	        // dangling-dep class (independent of the file/symbol axis; an item can
1321	        // be orphaned in both ways and will surface twice).
1322	        if let Some(deps) = tbl.get("depends_on").and_then(|v| v.as_array()) {
1323	            let mut missing: Vec<String> = Vec::new();
1324	            for dep in deps {
1325	                if let Some(d) = dep.as_str()
1326	                    && !known_ids.contains(d)
1327	                {
1328	                    missing.push(d.to_string());
1329	                }
1330	            }
1331	            if !missing.is_empty() {
1332	                let mut obj = serde_json::Map::new();
1333	                obj.insert("id".into(), JsonValue::String(id.into()));
1334	                obj.insert("class".into(), JsonValue::String("dangling-dep".into()));
1335	                obj.insert(
1336	                    "dangling_deps".into(),
1337	                    JsonValue::Array(missing.into_iter().map(JsonValue::String).collect()),
1338	                );
